/*
 * A042696  Numerators of continued fraction convergents to sqrt(878).
 * https://oeis.org/A042696
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the nth convergent of the continued *
 *            fraction for sqrt(878). * * The convergents P_k/Q_k are
 *            generated by the recurrence * P_{-2}=0, Q_{-2}=1 * P_{-1}=1,
 *            Q_{-1}=0 * P_k = a_k*P_{k-1} + P_{k-2} * Q_k = a_k*Q_{k-1} +
 *            Q_{k-2} * where a_0 = ⌊√878⌋ = 29 and a_1,a_2,… is the period...
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 19, u64 n <= 39, u128 n <= 83,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

/* ---------- helpers ---------- */
static inline uint64_t integer_sqrt_uint64(uint64_t n)
{
    uint64_t low = 0, high = n;
    while (low <= high) {
        uint64_t mid = (low + high) >> 1;
        __uint128_t sq = (__uint128_t)mid * mid;
        if (sq <= n) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
}

/* ---------- static cache ---------- */
static uint64_t  a0_global = 0;          /* a0 = floor(sqrt(878)) */
static size_t    period_len = 0;          /* length of the period */
static uint64_t *period_coeffs = NULL;   /* periodic a_k values after a0 */

static seq_t   *P = NULL;                /* stored numerators P_k   */
static size_t   P_cap = 0;               /* capacity of P          */
static idx_t    P_len = 0;               /* number of values stored */

static int initialized = 0;

/* ---------- initialise the period and first term ---------- */
static void init(void)
{
    if (initialized) return;
    initialized = 1;

    /* Compute a0 = floor(sqrt(878)) */
    const uint64_t D = 878ULL;
    a0_global = integer_sqrt_uint64(D);

    /* Compute the period of the continued fraction */
    uint64_t m = 0, d = 1, a = a0_global;
    size_t cap = 8;
    period_coeffs = (uint64_t *)malloc(cap * sizeof(uint64_t));
    size_t len = 0;
    while (1) {
        m = d * a - m;
        d = (D - m * m) / d;
        a = (a0_global + m) / d;          /* next coefficient */

        if (len == cap) {
            cap <<= 1;
            period_coeffs = (uint64_t *)realloc(period_coeffs,
                                                cap * sizeof(uint64_t));
        }
        period_coeffs[len++] = a;
        if (a == 2 * a0_global) break;    /* end of period */
    }
    period_len = len;

    /* Initialise array of numerators with the first term */
    P_cap = 16;
    P = (seq_t *)malloc(P_cap * sizeof(seq_t));
    P[0] = (seq_t)a0_global;
    P_len = 1;
}

/* ---------- ensure capacity of the P array ---------- */
static void ensure_P_capacity(size_t needed)
{
    if (needed <= P_cap) return;
    size_t new_cap = P_cap ? P_cap << 1 : 16;
    while (new_cap < needed) new_cap <<= 1;
    P = (seq_t *)realloc(P, new_cap * sizeof(seq_t));
    P_cap = new_cap;
}

/* ---------- public function ---------- */
seq_t a(idx_t n)
{
    if (!initialized) {
        init();
    }
    if (n < P_len) {
        return P[n];
    }

    /* compute missing numerators up to index n */
    seq_t prev2 = 1;                      /* P_{-1} */
    if (P_len >= 1) {
        prev2 = 1;
        prev2 = (P_len >= 2) ? P[P_len-2] : (seq_t)1;
    }
    seq_t prev1 = P[P_len-1];             /* P_{k-1} */

    size_t k = P_len;                     /* next index to compute */
    while (k <= (size_t)n) {
        /* coefficient a_k */
        seq_t ak;
        if (k == 0) {
            ak = (seq_t)a0_global;
        } else {
            ak = (seq_t)period_coeffs[(k - 1) % period_len];
        }

        /* P_k = a_k * P_{k-1} + P_{k-2} */
        seq_t cur = ak * prev1 + prev2;

        /* store */
        ensure_P_capacity(k + 1);
        P[k] = cur;

        /* shift for next iteration */
        prev2 = prev1;
        prev1 = cur;
        k++;
    }
    P_len = n + 1;
    return P[n];
}
